-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
local addon_name = ...
LibStub("AceLocale-3.0"):NewLocale(addon_name, "enUS", true, true)
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.rogue.dps.Name"] = "Melee DPS"
L["rm.era.rogue.dps.Description"] = "Levels 1–60, every spec, also on Hardcore and Self-Found realms; built from simulator, Icy Veins and Wowhead. From Stealth: Premeditation, Ambush with a dagger when the target is not facing you, Cheap Shot solo, Garrote outside raids. In combat: Riposte, Slice and Dice from one combo point when it is missing on an elite or a healthy target (renewed at five points in its last three seconds), Expose Armor at five points in a group when you have Improved Expose Armor 2/2 and nobody Sunders, a two-point Eviscerate on a target about to die, otherwise Eviscerate at five and no builder past five. The builder follows what you know: Ghostly Strike and Hemorrhage outside raids, Backstab with a dagger when the target is not facing you, else Sinister Strike. Reminders: poisons on each weapon (Deadly on an off-hand weapon when carried), Kick, Thistle Tea, Blade Flurry and Adrenaline Rush on elites or two enemies with Slice and Dice up, Cold Blood at five, Evasion solo when hurt. Vanish, Gouge, Preparation, Kidney Shot and racials are listed off; Feint, Sprint, Blind, Sap and positioning stay with you."
L["rm.era.rogue.dps.simulator.Name"] = "Swords, swing-synced Sinister Strike (simulator)"
L["rm.era.rogue.dps.simulator.Description"] = "The simulator \"sweaty\" Combat order for Sword Specialization, an alternative to the recommended melee DPS premade, off by default: enable it and disable that one, or raise its priority. Sinister Strike only right after a main-hand swing (2.0 seconds or more to the next one, set for a 2.6–2.8 speed sword; change it in a clone), unless energy is near full or the target is about to die, so the extra sword attack does not delay your swing. Eviscerate at five also waits for Slice and Dice, full energy or a dying target. Otherwise as the recommended premade."
L["rm.era.rogue.dps.warcrafttavern.Name"] = "Melee DPS, five-point finishers (Warcraft Tavern)"
L["rm.era.rogue.dps.warcrafttavern.Description"] = "Warcraft Tavern's way, an alternative to the recommended melee DPS premade, off by default: enable it and disable that one, or raise its priority. Every finisher waits for five combo points so Relentless Strikes refunds it. Slice and Dice is used from its second rank (level 42) when missing or ending, otherwise Eviscerate; no low-point Slice, no near-death Eviscerate and no Expose Armor (a warrior's Sunder covers it). Same openers, builders and reminders as the recommended premade."
L["rm.forever.rogue.dps.Name"] = "Melee DPS"
L["rm.forever.rogue.dps.Description"] = "Melee damage for every Rogue specialization from level 1 to 60, built from Icy Veins, Wowhead and Warcraft Tavern. The builder follows what you know: Mutilate (Sinister Strike for the fifth point), Hemorrhage, Backstab when the target is not facing you, else Sinister Strike. From Stealth it opens with Premeditation, Cheap Shot when solo, Garrote for Subtlety on group elites, else Ambush or Garrote. It keeps Slice and Dice and Venom up, uses Expose Armor in groups on elites when no warrior has five Sunders, then spends five points on Rupture (Subtlety, long fights) or Eviscerate, and never builds past five. Reminders: poisons on each weapon, Kick, Blade Flurry and Adrenaline Rush on packs and elites, Cold Blood, Evasion, Feint, Thistle Tea and Preparation. Left to you: Vanish, Sprint, Kidney Shot, Blind, Sap and positioning. Forever restricts combat data, so Rotation Master lists this premade for reference and does not select it automatically yet."
L["rm.forever.rogue.subtlety.warcrafttavern.Name"] = "Subtlety, Ambush build (Warcraft Tavern)"
L["rm.forever.rogue.subtlety.warcrafttavern.Description"] = "Warcraft Tavern's Ambush/Cutthroat Subtlety build: Premeditation and Ambush on every opener, Ambush again whenever Cutthroat allows it, Backstab from behind as the builder (Hemorrhage when the target is facing you), Ghostly Strike on cooldown, and Slice and Dice then Eviscerate at five points with no Rupture. Reminds you to Vanish for another Ambush on a tanked boss. Choose it instead of the recommended Rogue premade if you took the Cutthroat talents; it applies with Subtlety as your main talent tree and Cutthroat talented. Same poison and cooldown reminders as the recommended premade. An alternative to the recommended Rogue DPS premade, off by default: enable it and disable that one, or raise its priority."
L["rm.forever.rogue.subtlety.wowhead.Name"] = "Subtlety, Garrote build (Wowhead)"
L["rm.forever.rogue.subtlety.wowhead.Description"] = "Wowhead's Subtlety: Premeditation and Garrote on every opener, and Vanish (then Preparation) used in the rotation to open with Garrote again once the last one has run out. Slice and Dice kept up, Expose Armor in groups, Rupture as the five-point finisher, Hemorrhage as the only builder. This spends Vanish, your escape, on damage: choose it deliberately. It applies with Subtlety as your main talent tree, Dirty Deeds talented and Premeditation known. Same poison and cooldown reminders as the recommended premade. An alternative to the recommended Rogue DPS premade, off by default: enable it and disable that one, or raise its priority."
L["rm.mop.rogue.assassination.Name"] = "Recommended"
L["rm.mop.rogue.assassination.Description"] = "Recommended for Assassination, from level 10 to 90 (simulator and Wowhead for Phase 5, with Icy Veins' leveling steps). Opens from Stealth with Cheap Shot when solo, otherwise Mutilate (Dispatch on Blindside, with a dagger). Keeps Slice and Dice up (Envenom refreshes it from level 60) and Rupture on the target, spends five points on Envenom while Rupture lasts and four points to keep the Envenom buff rolling when you do not have Anticipation, then Marked for Death, Dispatch below 35% or on Blindside (it needs a dagger in the main hand), and Mutilate. Against four or more enemies fighting you: Slice and Dice, Crimson Tempest at seven, Rupture, Envenom and Fan of Knives; tabbing Rupture onto other targets is up to you. Solo it adds Recuperate and a Kidney Shot when you are low. Reminders: poisons, Kick, Vendetta on long fights, Shadow Blades with Vendetta, Vanish and Preparation inside Vendetta, Shadowstep from range, Evasion solo. Left to you: Tricks of the Trade and Expose Armor (listed but off), Feint, Sprint and positioning."
L["rm.mop.rogue.assassination.icyveins.Name"] = "Envenom at five (Icy Veins)"
L["rm.mop.rogue.assassination.icyveins.Description"] = "Off by default. The Icy Veins and Method order: Vanish on cooldown for a stealthed Mutilate, Vendetta on cooldown when the fight is long enough, Envenom only at five points, Rupture kept up, Dispatch below 35% or on Blindside, Mutilate. Four to eight enemies: Fan of Knives with Rupture at three points or more; nine or more: Fan of Knives and Envenom only. The recommended Assassination premade follows the newer Phase 5 advice instead; to use this one, enable it and disable the recommended one."
L["rm.mop.rogue.combat.Name"] = "Recommended"
L["rm.mop.rogue.combat.Description"] = "Recommended for Combat, from level 10 to 90 (Wowhead and simulator for Phase 5). Since the Siege of Orgrimmar patch Sinister Strike costs 50 energy, so Revealing Strike is the builder and Sinister Strike is used only under Bloodlust or Heroism with Adrenaline Rush (and before level 20). Opens with Cheap Shot solo, otherwise Ambush. Keeps Slice and Dice up from two points and Revealing Strike on the target, spends five points only while Revealing Strike is up (Slice and Dice, Rupture on a long single-target fight without Blade Flurry, Eviscerate) and waits for energy at five. Against eight or more enemies: Slice and Dice, Crimson Tempest and Fan of Knives. Solo it adds Recuperate and Kidney Shot. Reminders: poisons, Kick, Blade Flurry on against two or more enemies and off again, Adrenaline Rush at low energy with Shadow Blades, Killing Spree, Vanish and Preparation for Ambush in Deep Insight, Shadowstep, Evasion solo. Left to you: Tricks of the Trade and Expose Armor (listed but off), Feint and positioning behind the target for Ambush."
L["rm.mop.rogue.combat.hekili.Name"] = "Anticipation (Hekili)"
L["rm.mop.rogue.combat.hekili.Description"] = "Off by default. The Hekili MoP order for Combat with Anticipation: Revealing Strike is the only builder, even under Bloodlust; finishers wait for Deep Insight, four Anticipation charges or Shadow Blades coming back, then Slice and Dice, Rupture on one or two long-lived targets, Crimson Tempest at seven enemies and Eviscerate; Slice and Dice is refreshed early at 11 Bandit's Guile stacks; Fan of Knives from four enemies. It applies only with Anticipation talented. Enable it and disable the recommended Combat premade to use it."
L["rm.mop.rogue.combat.icyveins.Name"] = "Sinister Strike builder (Icy Veins)"
L["rm.mop.rogue.combat.icyveins.Description"] = "Off by default, and superseded for Phase 5. The Icy Veins, Warcraft Tavern, Method and wowtbc.gg order from before the Siege of Orgrimmar patch: Slice and Dice, Revealing Strike kept up, five-point Rupture on a long single-target fight and Eviscerate, with Sinister Strike as the builder. Same reminders and pack play as the recommended Combat premade. Choose it only if you follow those guides; enable it and disable the recommended one."
L["rm.mop.rogue.subtlety.Name"] = "Recommended"
L["rm.mop.rogue.subtlety.Description"] = "Recommended for Subtlety with Shadow Focus, from level 10 to 90 (simulator and Wowhead for Phase 5). In Stealth or Shadow Dance: Premeditation, Slice and Dice before the pull, finishers at five points, Ambush, Garrote. Outside: Slice and Dice; at five points Slice and Dice and Rupture when they are about to drop, Eviscerate while both last; Marked for Death; Hemorrhage to keep its bleed; Backstab (with a dagger) when the target is not attacking you, otherwise Hemorrhage. Against three or more enemies: Slice and Dice, Crimson Tempest, Eviscerate and Fan of Knives. Solo it adds Recuperate and Kidney Shot. Reminders: poisons, Kick, Shadow Dance at 75 energy with Slice and Dice and Rupture up, Vanish when Find Weakness is ending, Preparation, Shadow Blades outside Dance and Stealth, Shadowstep, Evasion solo. Left to you: standing behind the target (RM cannot see facing), Tricks of the Trade and Expose Armor (listed but off)."
L["rm.mop.rogue.subtlety.warcrafttavern.Name"] = "Subterfuge (Warcraft Tavern)"
L["rm.mop.rogue.subtlety.warcrafttavern.Description"] = "Chosen automatically instead of the Shadow Focus premade when your tier-1 talent is Subterfuge (Warcraft Tavern's build). Premeditation and Slice and Dice before the pull; in Stealth, Shadow Dance or the Subterfuge linger, finishers at five points and then Ambush as often as it lands. Two or three enemies: keep Rupture up and spend five points on Crimson Tempest instead of Eviscerate; four or more add Fan of Knives. One target: Slice and Dice, Rupture, Eviscerate, Hemorrhage for its bleed, Backstab from behind with a dagger, else Hemorrhage. Shadow Dance and Vanish are reminders at 60 energy with Slice and Dice up; timing them to trinket procs, as Tavern suggests, is up to you."
L["rm.mop.rogue.unspecialized.Name"] = "Unspecialized"
L["rm.mop.rogue.unspecialized.Description"] = "For levels 1 to 9, or a rogue who has not chosen a specialization yet; each specialization's premade takes over once you pick one. Opens from Stealth with Cheap Shot when solo, Ambush or Sinister Strike; suggests Stealth out of combat; Slice and Dice from two points, Recuperate and Kidney Shot when solo and hurt, Eviscerate at four points (two when the target is about to die), Sinister Strike. Reminders: poisons once learned, Kick, Evasion solo."
L["rm.retail.rogue.assassination.Name"] = "Blizzard Assisted"
L["rm.retail.rogue.assassination.Description"] = "Recommended for Assassination in Midnight. In combat the game now hides your bleeds, buffs, energy, cooldown times and health from addons, so this shows Blizzard's own Assisted Combat suggestion (the one-button rotation, which handles the stealth opener, Garrote, Rupture, Envenom, Deathmark and Kingsbane), and stops while you cast or have no enemy targeted. Reminders for what it leaves out: a lethal and a non-lethal poison and Stealth between pulls, Vanish when you are out of stealth in combat, Kick on an interruptible cast (it lights only where the game lets the cast be read). Health is hidden on Retail, so Crimson Vial is your call."
L["rm.retail.rogue.assassination.icyveins.Name"] = "Reference (Icy Veins)"
L["rm.retail.rogue.assassination.icyveins.Description"] = "Reference only, off by default: the Icy Veins and SimulationCraft order keeps bleeds up by their timers, which Midnight hides in combat; energy is hidden on Retail, so its energy pooling is left out. From stealth Garrote, then Ambush. Garrote in its last 30% while you are not at full combo points, Rupture at 5+ in its last 30%; at 5+ combo points Coup de Grace or Envenom; below, Crimson Tempest on three or more enemies, Fan of Knives on two or more close by, Ambush, Mutilate. Reminders: Deathmark with both bleeds up, Kingsbane alongside it, Vanish with Deathmark ready, Shiv on a Deathstalker's Mark target, Thistle Tea whenever it is ready in combat, plus the shared poison, Stealth and Kick reminders."
L["rm.retail.rogue.initial.Name"] = "Blizzard Assisted"
L["rm.retail.rogue.initial.Description"] = "Recommended before you choose a specialization (while the game reports the Rogue's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests next, the one rotation advice the game still lets an addon read in Midnight combat; it waits while you cast or channel. Alongside it, the reminders every Rogue premade shares, each once you know its spell. When you choose a specialization at level 10, that specialization's premades take over."
L["rm.retail.rogue.outlaw.Name"] = "Blizzard Assisted"
L["rm.retail.rogue.outlaw.Description"] = "Recommended for Outlaw in Midnight. Shows Blizzard's Assisted Combat suggestion (it handles the stealth opener, Roll the Bones, Blade Flurry, Adrenaline Rush, Between the Eyes and the finishers), and stops while you cast or have no enemy targeted. Reminders for what it leaves out: poisons and Stealth between pulls, Vanish when you are out of stealth in combat, Kick. Health is hidden on Retail, so Crimson Vial is your call. Keep It Rolling stays with you: the game hides how many Roll the Bones buffs you have."
L["rm.retail.rogue.outlaw.icyveins.Name"] = "Reference (Icy Veins)"
L["rm.retail.rogue.outlaw.icyveins.Description"] = "Reference only, off by default: the Icy Veins, SimulationCraft and Wowhead order reads Roll the Bones buffs, Opportunity stacks and energy, which Midnight hides in combat. From stealth Ambush. One combo point short of full or more: Between the Eyes, Killing Spree, Coup de Grace, Dispatch. Otherwise Ambush with Audacity, Pistol Shot at six Opportunity stacks (three when low on combo points), Ambush, Sinister Strike. Reminders: Roll the Bones with no roll up, Adrenaline Rush at two or fewer combo points, Blade Flurry kept up on two or more enemies, Blade Rush, Preparation when Adrenaline Rush, Between the Eyes and Blade Rush are all cooling. Keep It Rolling stays manual."
L["rm.retail.rogue.subtlety.Name"] = "Blizzard Assisted"
L["rm.retail.rogue.subtlety.Description"] = "Recommended for Subtlety in Midnight. Shows Blizzard's Assisted Combat suggestion (it handles the stealth opener, Shadow Blades, Goremaw's Bite, Shadow Dance, Secret Technique and the finishers), and stops while you cast or have no enemy targeted. Reminders for what it leaves out: poisons and Stealth between pulls, Kick on an interruptible cast. Health is hidden on Retail, so Crimson Vial is your call."
L["rm.retail.rogue.subtlety.icyveins.Name"] = "Reference (Icy Veins)"
L["rm.retail.rogue.subtlety.icyveins.Description"] = "Reference only, off by default: the Icy Veins and SimulationCraft order holds Shadow Dance for Secret Technique and reads Shadow Dance, Darkest Night and energy, which Midnight hides in combat. Stealthed before the pull: Shadowstrike. One combo point short of full or more: Eviscerate with Darkest Night, Secret Technique in Shadow Dance, Coup de Grace, Black Powder on three or more enemies, Eviscerate. Otherwise Shadowstrike, Shuriken Storm on two or more, Gloomblade or Backstab. Reminders: Goremaw's Bite in Shadow Dance, Shadow Blades with Shadow Dance ready, Shadow Dance at two or fewer (or six or more) combo points when Secret Technique is ready or Shadow Blades is up, Vanish out of stealth at two or fewer combo points."
L["rm.sod.rogue.dps.Name"] = "Melee DPS (SoD)"
L["rm.sod.rogue.dps.Description"] = "Season of Discovery, levels 1–60 with runes as you engrave them; built from simulator Phase 6, Icy Veins and Zockify Phase 8. From Stealth: Shadowstrike, Garrote in a group, Ambush for a Backstab build with a dagger, Cheap Shot solo. On three or more enemies fighting you: Blunderbuss, Crimson Tempest, Fan of Knives first. Then Ambush on a Cutthroat proc (with a dagger), Saber Slash kept at three stacks, Poisoned Knife at four poison stacks, Slice and Dice from two points (renewed from four, unless Cut to the Chase is engraved), Expose Armor duty when nobody Sunders or keeps Sebacious Poison up, with Carnage engraved a bleed (Crimson Tempest, else Rupture; none with Saber Slash), Envenom at five (Eviscerate until you engrave it), and a builder by glove rune: Mutilate, Saber Slash, Backstab (with a dagger), else Sinister Strike. Reminders: a temporary enchant on each weapon, Kick, Thistle Tea, Blade Flurry, Adrenaline Rush, Cold Blood and Evasion, and with Master of Subtlety engraved Vanish to renew it and Preparation."
L["rm.sod.rogue.dps.icyveins.Name"] = "Melee DPS, Rupture for Carnage (SoD, Icy Veins)"
L["rm.sod.rogue.dps.icyveins.Description"] = "Icy Veins' Season of Discovery order, an alternative to the recommended Season of Discovery melee DPS premade, off by default: enable it and disable that one, or raise its priority. Every finisher at five combo points, first Slice and Dice when missing or ending, then Rupture kept up when Carnage is engraved, then Envenom; Poisoned Knife only at five poison stacks; Blunderbuss or Fan of Knives on three enemies. Same openers, builders and reminders as the recommended premade; Sebacious Poison duty stays with you."
L["rm.sod.rogue.dps.zockify.Name"] = "Melee DPS, lean Envenom (SoD, Zockify)"
L["rm.sod.rogue.dps.zockify.Description"] = "Zockify's lean Season of Discovery list, an alternative to the recommended Season of Discovery melee DPS premade, off by default: enable it and disable that one, or raise its priority. No bleeds and no Expose Armor. Poisoned Knife at four poison stacks, Slice and Dice when missing (from two points, four with Saber Slash), Envenom at five, then the glove-rune builder. The Vanish and Cold Blood burst stays with you."
L["rm.sod.rogue.tank.Name"] = "Tank (SoD)"
L["rm.sod.rogue.tank.Description"] = "Season of Discovery tank, chosen when Just a Flesh Wound is engraved; built from simulator Phase 6, Icy Veins, Zockify and Warcraft Tavern. Riposte, Main Gauche on cooldown, Blade Dance from one combo point (renewed from three), Slice and Dice from three (renewed from four), Fan of Knives, Crimson Tempest and Blunderbuss on three or more enemies, Blunderbuss while Blade Dance is up, Eviscerate at five with both buffs up, Poisoned Knife at low energy, then Saber Slash, Mutilate or Sinister Strike. Reminders: Tease in a group when your target attacks someone else, Kick, Evasion below half health, Blade Flurry, Adrenaline Rush, Thistle Tea and weapon poisons (the off-hand one only with an off-hand weapon). Shadowstep and Sebacious Poison duty stay with you."
L["rm.tbc.rogue.dps.simulator.Name"] = "Melee DPS (simulator)"
L["rm.tbc.rogue.dps.simulator.Description"] = "Levels 1–70, every spec. From stealth: Premeditation, then Cheap Shot solo or Garrote in a group, otherwise Ambush (with a dagger in the main hand). In combat: Riposte, Slice and Dice from two combo points (renewed in its last two seconds), Eviscerate on a target about to die, and at five points Rupture when it will last (not while Blade Flurry cleaves), otherwise Eviscerate. Builds with Mutilate or Backstab (dagger) when the target is not attacking you, otherwise Hemorrhage or Sinister Strike. Reminds you of missing poisons, Kick, Blade Flurry and Adrenaline Rush, Cold Blood and Evasion. Expose Armor, Kidney Shot, Feint, Vanish and positioning stay with you."
L["rm.tbc.rogue.dps.wowhead.Name"] = "Melee DPS (Wowhead)"
L["rm.tbc.rogue.dps.wowhead.Description"] = "Levels 1–70, every spec, following Wowhead. Same stealth openers, builders and reminders as the simulator version, but Slice and Dice starts from one combo point and every five-point finisher is Eviscerate: no Rupture. Expose Armor, Kidney Shot, Feint, Vanish and positioning stay with you. An alternative to the recommended simulator melee DPS premade, off by default: enable it and disable that one, or raise its priority."
